 tasks.add(dep);
 if (!adj.has(dep)) adj.set(dep, []);
 if (!inDegree.has(dep)) inDegree.set(dep, 0);
 }
 // dep must come before task, so task depends on dep
 // inDegree[task] counts unresolved dependencies
 if (!inDegree.has(task)) inDegree.set(task, 0);
 inDegree.set(task, inDegree.get(task) + 1);
 }
 }

 // Kahn's algorithm with lexicographic ordering
 const queue = [];
