def allocate(total, weights):
    if total < 0:
        raise ValueError("total must be non-negative")
    if not weights:
        raise ValueError("weights must not be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights must be non-negative")
    if sum(weights) == 0:
        raise ValueError("weights cannot all be zero")

    n = len(weights)
    total_weight = sum(weights)
    floors = [w * total // total_weight for w in weights]
    remainder = total - sum(floors)
    if remainder == 0:
        return floors
    fractions = [w * total % total_weight for w in weights]
    # Sort by (-fraction, index) to get largest remainders first, ties broken by lower index
    sorted_indices = sorted(range(n), key=lambda i: (-fractions[i], i))
    for i in sorted_indices[:remainder]:
        floors[i] += 1
    return floors
