def to_24h(text):
    if not isinstance(text, str):
        raise TypeError("Input must be a string")

    text = text.strip()
    if not text:
        raise ValueError("Empty text")

    # Split into time part and suffix
    parts = text.split()
    if len(parts) > 2:
        raise ValueError("Too many parts")

    time_part = parts[0]
    suffix = parts[1] if len(parts) == 2 else ""

    # Validate suffix
    if not suffix:
        raise ValueError("Missing AM/PM")
    suffix_upper = suffix.upper()
    if suffix_upper not in ("AM", "PM"):
        raise ValueError("Unknown suffix")

    # Parse time part
    if ':' not in time_part:
        raise ValueError("Missing colon")

    hour_str, minute_str = time_part.split(':')

    if not hour_str or not minute_str:
        raise ValueError("Invalid time format")

    # Validate hour
    hour = int(hour_str)
    if hour < 1 or hour > 12:
        raise ValueError("Hour must be between 1 and 12")

    # Validate minutes
