def maze_steps(grid):
    if not grid:
        return -1

    rows = len(grid)
    cols = len(grid[0])

    # Validate grid dimensions
    for row in grid:
        if len(row) != cols:
            raise ValueError("All rows must have the same length")

    # Validate characters and count S and E
    start = None
    end = None
    for r in range(rows):
        for c in range(cols):
            ch = grid[r][c]
            if ch not in 'S.E#.':
                raise ValueError(f"Invalid character '{ch}' in grid")
            if ch == 'S':
                if start is not None:
                    raise ValueError("Multiple start points found")
                start = (r, c)
            elif ch == 'E':
                if end is not None:
                    raise ValueError("Multiple end points found")
                end = (r, c)

    if start is None or end is None:
        raise ValueError("Exactly one 'S' and one 'E' must be present")

    # BFS to find shortest path
    from collections import deque
    queue = deque()
    visited = set()
    queue.append((start[0], start[1], 0))
    visited.add(start)

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        r, c, dist = queue.popleft()
        if (r, c) == end:
            return dist
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] in 'S.E#' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc, dist + 1))

    return -1
